package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="contribuicao",schema="adm_eclesial") public class Contribuicao { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="organizacao_eclesial_id",nullable=false) Long organizacaoEclesialId; @Column(name="pessoa_id") Long pessoaId; @Column(name="dizimista_id") Long dizimistaId; @Column(name="categoria_financeira_id",nullable=false) Long categoriaFinanceiraId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) TipoContribuicao tipo; @Column(nullable=false,precision=15,scale=2) BigDecimal valor; @Column(name="data_contribuicao",nullable=false) LocalDate dataContribuicao; @Column LocalDate competencia; @Enumerated(EnumType.STRING) @Column(name="meio_recebimento",nullable=false,length=20) MeioRecebimento meioRecebimento; @Column(columnDefinition="text") String observacao; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getOrganizacaoEclesialId(){return organizacaoEclesialId;} public Long getPessoaId(){return pessoaId;} public Long getDizimistaId(){return dizimistaId;} public Long getCategoriaFinanceiraId(){return categoriaFinanceiraId;} public TipoContribuicao getTipo(){return tipo;} public BigDecimal getValor(){return valor;} public LocalDate getDataContribuicao(){return dataContribuicao;} public LocalDate getCompetencia(){return competencia;} public MeioRecebimento getMeioRecebimento(){return meioRecebimento;} public String getObservacao(){return observacao;} public void setOrganizacaoEclesialId(Long v){organizacaoEclesialId=v;} public void setPessoaId(Long v){pessoaId=v;} public void setDizimistaId(Long v){dizimistaId=v;} public void setCategoriaFinanceiraId(Long v){categoriaFinanceiraId=v;} public void setTipo(TipoContribuicao v){tipo=v;} public void setValor(BigDecimal v){valor=v;} public void setDataContribuicao(LocalDate v){dataContribuicao=v;} public void setCompetencia(LocalDate v){competencia=v;} public void setMeioRecebimento(MeioRecebimento v){meioRecebimento=v;} public void setObservacao(String v){observacao=v;} }